#define AVX2_LOOKUP4_FIRST(IDX, OFF) \
	VPEXTRB	$IDX, X0, AX; \
	SHLQ	$4, AX; \
	VMOVDQU	OFF(DX)(AX*1), X2; \
	VPEXTRB	$IDX, X4, AX; \
	SHLQ	$4, AX; \
	VMOVDQU	OFF(DX)(AX*1), X6; \
	VPEXTRB	$IDX, X8, AX; \
	SHLQ	$4, AX; \
	VMOVDQU	OFF(DX)(AX*1), X10; \
	VPEXTRB	$IDX, X12, AX; \
	SHLQ	$4, AX; \
	VMOVDQU	OFF(DX)(AX*1), X14

#define AVX2_LOOKUP4_XOR(IDX, OFF) \
	VPEXTRB	$IDX, X0, AX; \
	SHLQ	$4, AX; \
	VMOVDQU	OFF(DX)(AX*1), X3; \
	VPXOR	X3, X2, X2; \
	VPEXTRB	$IDX, X4, AX; \
	SHLQ	$4, AX; \
	VMOVDQU	OFF(DX)(AX*1), X3; \
	VPXOR	X3, X6, X6; \
	VPEXTRB	$IDX, X8, AX; \
	SHLQ	$4, AX; \
	VMOVDQU	OFF(DX)(AX*1), X3; \
	VPXOR	X3, X10, X10; \
	VPEXTRB	$IDX, X12, AX; \
	SHLQ	$4, AX; \
	VMOVDQU	OFF(DX)(AX*1), X3; \
	VPXOR	X3, X14, X14

#define AVX2_LOOKUP4_FIRST_B(IDX, OFF) \
	VPEXTRB	$IDX, X1, AX; \
	SHLQ	$4, AX; \
	VMOVDQU	OFF(DX)(AX*1), X2; \
	VPEXTRB	$IDX, X5, AX; \
	SHLQ	$4, AX; \
	VMOVDQU	OFF(DX)(AX*1), X6; \
	VPEXTRB	$IDX, X9, AX; \
	SHLQ	$4, AX; \
	VMOVDQU	OFF(DX)(AX*1), X10; \
	VPEXTRB	$IDX, X13, AX; \
	SHLQ	$4, AX; \
	VMOVDQU	OFF(DX)(AX*1), X14

#define AVX2_LOOKUP4_XOR_B(IDX, OFF) \
	VPEXTRB	$IDX, X1, AX; \
	SHLQ	$4, AX; \
	VMOVDQU	OFF(DX)(AX*1), X3; \
	VPXOR	X3, X2, X2; \
	VPEXTRB	$IDX, X5, AX; \
	SHLQ	$4, AX; \
	VMOVDQU	OFF(DX)(AX*1), X3; \
	VPXOR	X3, X6, X6; \
	VPEXTRB	$IDX, X9, AX; \
	SHLQ	$4, AX; \
	VMOVDQU	OFF(DX)(AX*1), X3; \
	VPXOR	X3, X10, X10; \
	VPEXTRB	$IDX, X13, AX; \
	SHLQ	$4, AX; \
	VMOVDQU	OFF(DX)(AX*1), X3; \
	VPXOR	X3, X14, X14

#define AVX2_LOOKUP4_BLOCK() \
	AVX2_LOOKUP4_FIRST(0, 0); \
	AVX2_LOOKUP4_XOR(1, 4096); \
	AVX2_LOOKUP4_XOR(2, 8192); \
