cmAVX2Block:
	MOVQ	R9, R15
	BSWAPQ	R15
	MOVQ	R15, 0(SP)
	MOVQ	R14, 8(SP)
	MOVQ	R9, R15
	ADDQ	$1, R15
	BSWAPQ	R15
	MOVQ	R15, 16(SP)
	MOVQ	R14, 24(SP)
	MOVQ	R9, R15
	ADDQ	$2, R15
	BSWAPQ	R15
	MOVQ	R15, 32(SP)
