	VPXOR	X1, X0, X0
	VPXOR	X1, X4, X4
	VPXOR	X1, X8, X8
	VPXOR	X1, X12, X12
	AVX2_LOOKUP4_BLOCK()
	ADDQ	$16, SI
	VMOVDQU	X2, X0
	VMOVDQU	X6, X4
	VMOVDQU	X10, X8
	VMOVDQU	X14, X12
	SUBQ	$1, DI
	JNZ	cmAVX2Round

	VMOVDQU	(SI), X1
	VPXOR	X1, X0, X0
	VPXOR	X1, X4, X4
	VPXOR	X1, X8, X8
	VPXOR	X1, X12, X12
	VPXOR	X0, X5, X5
	VPXOR	X4, X9, X9
	VPXOR	X8, X13, X13
	VPXOR	X12, X15, X15
	VMOVDQU	X5, 0(R12)
	VMOVDQU	X9, 16(R12)
	VMOVDQU	X13, 32(R12)
	VMOVDQU	X15, 48(R12)

	ADDQ	$64, R12
	ADDQ	$4, R9
	SUBQ	$1, R13
	JNZ	cmAVX2Block

cmAVX2Done:
	VZEROUPPER
	RET

